-- Drop existing tables (ignore errors if they do not exist yet)
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE ATTENDANCE CASCADE CONSTRAINTS PURGE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE MARKS CASCADE CONSTRAINTS PURGE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE SUBJECTS CASCADE CONSTRAINTS PURGE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE STUDENTS CASCADE CONSTRAINTS PURGE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
CREATE TABLE STUDENTS (
  STUDENT_ID   NUMBER PRIMARY KEY,
  STUDENT_NAME VARCHAR2(100) NOT NULL,
  GENDER       VARCHAR2(10),
  DEPARTMENT   VARCHAR2(50),
  EMAIL        VARCHAR2(100),
  PHONE        VARCHAR2(15)
);

CREATE TABLE SUBJECTS (
  SUBJECT_ID   NUMBER PRIMARY KEY,
  SUBJECT_NAME VARCHAR2(100) NOT NULL,
  CREDITS      NUMBER
);

CREATE TABLE MARKS (
  MARK_ID    NUMBER PRIMARY KEY,
  STUDENT_ID NUMBER,
  SUBJECT_ID NUMBER,
  MARKS      NUMBER,
  EXAM_DATE  DATE,
  CONSTRAINT FK_STUDENT FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS (STUDENT_ID),
  CONSTRAINT FK_SUBJECT FOREIGN KEY (SUBJECT_ID) REFERENCES SUBJECTS (SUBJECT_ID)
);

CREATE TABLE ATTENDANCE (
  ATTENDANCE_ID    NUMBER PRIMARY KEY,
  STUDENT_ID       NUMBER,
  TOTAL_CLASSES    NUMBER,
  ATTENDED_CLASSES NUMBER,
  CONSTRAINT FK_ATTENDANCE FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS (STUDENT_ID)
);

