-- Quick checks (expected: 1000 students, 15 subjects, 6000 marks, 1000 attendance)
SELECT 'STUDENTS' AS tbl, COUNT(*) AS row_count FROM STUDENTS
UNION ALL SELECT 'SUBJECTS', COUNT(*) FROM SUBJECTS
UNION ALL SELECT 'MARKS', COUNT(*) FROM MARKS
UNION ALL SELECT 'ATTENDANCE', COUNT(*) FROM ATTENDANCE;


--- Oracle’s rule: To insert many rows in one go with INSERT ALL, Oracle requires the statement to end with a SELECT--- 
---It’s just grammar. Without that line, Oracle doesn’t know the statement is finished and gives an error.---